<!-- Generated by Trae Work -->
(function () {
  if (typeof echarts === 'undefined') return;
  var style = getComputedStyle(document.documentElement);
  var accent = style.getPropertyValue('--accent').trim();
  var accent2 = style.getPropertyValue('--accent2').trim();
  var ink = style.getPropertyValue('--ink').trim();
  var muted = style.getPropertyValue('--muted').trim();
  var rule = style.getPropertyValue('--rule').trim();
  var bg2 = style.getPropertyValue('--bg2').trim();
  var ok = style.getPropertyValue('--ok').trim();
  var warn = style.getPropertyValue('--warn').trim();

  /* ---- 图1 · 三阶段优化项落地状态 ---- */
  var el1 = document.getElementById('chart-status');
  if (el1) {
    var c1 = echarts.init(el1, null, { renderer: 'svg' });
    c1.setOption({
      animation: false,
      tooltip: { trigger: 'axis', axisPointer: { type: 'shadow' }, appendToBody: true },
      legend: {
        top: 0,
        data: ['已落地', '部分达成', '后续迭代'],
        icon: 'roundRect',
        itemWidth: 14, itemHeight: 6,
        textStyle: { color: muted }
      },
      grid: { left: 44, right: 20, top: 40, bottom: 30 },
      xAxis: {
        type: 'category',
        data: ['P1 结构性修复', 'P2 低成本高收益', 'P3 一次性收敛'],
        axisLine: { lineStyle: { color: rule } },
        axisTick: { show: false },
        axisLabel: { color: muted }
      },
      yAxis: {
        type: 'value',
        minInterval: 1,
        axisLabel: { color: muted },
        splitLine: { lineStyle: { color: rule } }
      },
      series: [
        {
          name: '已落地', type: 'bar', stack: 't', barWidth: 52,
          itemStyle: { color: ok, borderRadius: [0, 0, 0, 0] },
          data: [5, 6, 6]
        },
        {
          name: '部分达成', type: 'bar', stack: 't',
          itemStyle: { color: warn },
          data: [0, 0, 1]
        },
        {
          name: '后续迭代', type: 'bar', stack: 't',
          itemStyle: { color: mute(accent) },
          data: [1, 0, 0]
        }
      ]
    });
    window.addEventListener('resize', function () { c1.resize(); });
  }

  /* ---- 图2 · vLLM 热备 vs 冷启动 ---- */
  var el2 = document.getElementById('chart-vllm');
  if (el2) {
    var c2 = echarts.init(el2, null, { renderer: 'svg' });
    c2.setOption({
      animation: false,
      tooltip: { trigger: 'axis', axisPointer: { type: 'shadow' }, appendToBody: true,
        formatter: function (p) {
          var v = p[0].value;
          return p[0].name + '<br/>切换回对话等待：<b>' + v + '</b>';
        } },
      grid: { left: 60, right: 20, top: 20, bottom: 30 },
      xAxis: {
        type: 'category',
        data: ['轻量切换（设置/日志/学习视图）', '重显存切换（绘画/视频/训练）'],
        axisLine: { lineStyle: { color: rule } },
        axisTick: { show: false },
        axisLabel: { color: muted, fontSize: 11 }
      },
      yAxis: {
        type: 'value',
        name: '等待（秒）',
        nameTextStyle: { color: muted },
        axisLabel: { color: muted },
        splitLine: { lineStyle: { color: rule } }
      },
      series: [{
        type: 'bar', barWidth: '40%',
        itemStyle: {
          color: function (p) {
            return p.dataIndex === 0 ? ok : accent2;
          },
          borderRadius: [6, 6, 0, 0]
        },
        label: { show: true, position: 'top', color: ink, fontWeight: 700,
          formatter: function (p) { return p.value + ' s'; } },
        data: [0.5, 120]
      }]
    });
    window.addEventListener('resize', function () { c2.resize(); });
  }

  /* ---- 图3 · 回归通过分布 ---- */
  var el3 = document.getElementById('chart-reg');
  if (el3) {
    var c3 = echarts.init(el3, null, { renderer: 'svg' });
    c3.setOption({
      animation: false,
      tooltip: { trigger: 'item', appendToBody: true },
      legend: { bottom: 0, icon: 'circle', itemWidth: 10, itemHeight: 10, textStyle: { color: muted } },
      color: [accent, accent2, ok, warn],
      series: [{
        type: 'pie', radius: ['46%', '70%'],
        itemStyle: { borderColor: bg2, borderWidth: 2 },
        label: {
          formatter: '{b}\n{c} 项 ({d}%)',
          color: ink, fontSize: 12
        },
        data: [
          { name: 'L1 后端 pytest：通过', value: 108 },
          { name: 'L1 gated 跳过（GPU 集成/压力）', value: 5 },
          { name: 'L2 前端 vitest：通过', value: 55 },
          { name: 'tsc --noEmit 错误', value: 0 }
        ]
      }]
    });
    window.addEventListener('resize', function () { c3.resize(); });
  }

  function mute(color) {
    // 返回带透明度的版本用于“后续迭代/低优先级”等弱强调
    try {
      var r = parseInt(color.slice(1, 3), 16);
      var g = parseInt(color.slice(3, 5), 16);
      var b = parseInt(color.slice(5, 7), 16);
      return 'rgba(' + r + ',' + g + ',' + b + ',0.45)';
    } catch (e) { return color; }
  }
})();